import hashlib,json,os,statistics,subprocess,time,sys
base=Path.cwd();task=base/'.local/tool-tasks/policy-blocked-recovery-20261007'
templates=json.loads((task/'commands.json').read_text())
artifacts={'A':base/'.local/tool-tasks/open-potion-primary-proof-20261007/build-candidate-v4/CombatSolver.dll','C':task/'build-candidate/CombatSolver.dll'}
scenes=sys.argv[1:] or ['dev-02-defect-elite','dev-06-silent-boss','dev-09-necrobinder-boss']
records=[]
for scene in scenes:
 for label in ['A1','C1','C2','A2']:
  out=task/'pure'/scene/label;out.mkdir(parents=True,exist_ok=False)
  cmd=templates[scene].copy();cmd[cmd.index('--out')+1]=str(out);cmd[cmd.index('--label')+1]='policy-blocked-recovery-'+scene+'-'+label
  dll=artifacts[label[0]];env=os.environ.copy();env['OFFLINE_HARNESS_COMBATSOLVER_DLL']=str(dll)
  for key in list(env):
   if (key.startswith('OFFLINE_HARNESS_') and key!='OFFLINE_HARNESS_COMBATSOLVER_DLL') or key.startswith('COMBATSOLVER_VERIFY') or key in ['DOTNET_PerfMapEnabled','COMPlus_PerfMapEnabled','COMBATSOLVER_MEASUREMENT_TRACE']:env.pop(key,None)
  plan={'command':cmd,'dll':str(dll),'dllSha256':hashlib.sha256(dll.read_bytes()).hexdigest(),'outerTimeoutSeconds':120,'requestSha256':hashlib.sha256(Path(cmd[cmd.index('--request')+1]).read_bytes()).hexdigest(),'noProfilerOrCorrectnessInstrumentation':True}
  (out/'command.json').write_text(json.dumps(plan,indent=2)+'\n')
  started=time.monotonic()
  with (out/'launcher.log').open('w') as log:
   proc=subprocess.Popen(cmd,env=env,stdout=log,stderr=subprocess.STDOUT)
   try:code=proc.wait(timeout=120);status='Completed' if code==0 else 'Failed'
   except subprocess.TimeoutExpired:proc.kill();proc.wait();code=proc.returncode;status='TimeoutNoRetry'
  record={'scene':scene,'label':label,'status':status,'exit_code':code,'launcherWallSeconds':time.monotonic()-started,'plan':plan,'resultPath':str(out/'result.json')}
  if status=='Completed':
   result=json.loads((out/'result.json').read_text())
   for key in ['wallSeconds','peakProcessWorkingSetBytes','comparisonQuality','budget','solverMetrics','pruneCounters','timeBoundaryObserved']:record[key]=result[key]
   record['rootStampSha256']=hashlib.sha256(result['rootContinuationStamp'].encode()).hexdigest();record['policy']=json.loads((out/'search-policy.json').read_text());record['resultSha256']=hashlib.sha256((out/'result.json').read_bytes()).hexdigest()
  records.append(record);(task/'pure-summary.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n')
  print(json.dumps({key:record.get(key) for key in ['scene','label','status','wallSeconds','peakProcessWorkingSetBytes','comparisonQuality']},ensure_ascii=False),flush=True)
  if status!='Completed':raise SystemExit('Terminal result retained, no unchanged retry.')
 grouped={s:[r for r in records if r['scene']==s] for s in scenes}
 summaries={}
 for name,runs in grouped.items():
  if len(runs)!=4:continue
  controls=[r for r in runs if r['label'].startswith('A')];candidates=[r for r in runs if r['label'].startswith('C')]
  summaries[name]={'speedup':statistics.mean(r['wallSeconds'] for r in controls)/statistics.mean(r['wallSeconds'] for r in candidates),'peakRssRatio':max(r['peakProcessWorkingSetBytes'] for r in candidates)/max(r['peakProcessWorkingSetBytes'] for r in controls),'all14QualityEqual':all(r['comparisonQuality']==runs[0]['comparisonQuality'] for r in runs),'rootPolicyBudgetEqual':all((r['rootStampSha256'],r['policy'],r['budget'])==(runs[0]['rootStampSha256'],runs[0]['policy'],runs[0]['budget']) for r in runs),'timeBoundaryObserved':any(r['timeBoundaryObserved'] for r in runs)}
 (task/'pure-verification.json').write_text(json.dumps(summaries,ensure_ascii=False,indent=2)+'\n')
 if len(grouped[scene])==4:
  checked=summaries[scene];print('COMPARISON '+json.dumps({scene:checked}),flush=True)
  if not checked['all14QualityEqual'] or not checked['rootPolicyBudgetEqual'] or checked['peakRssRatio']>1.1 or checked['timeBoundaryObserved']:raise SystemExit('New candidate failed acceptance constraint; inspect before continuation.')

