namespace CombatSolver;
internal sealed partial class CombatBeamSolver
{
    internal (bool expanded, bool local, bool component) TaskPolicyRecoveryFlags()
        => (UsesExpandedHealingProof, CanUseLocalPrimaryHpBound, UsesComponentHealingProof);
}
internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskPolicyBlockedRecoveryAsync(CombatState live, Player player)
    {
        await Task.Yield();
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        if (root.CanCertifyRemainingHealing || !root.UsesPruningComponentHealingCertificate
            || root.InitialPruningHealingUpperBound != int.MaxValue
            || !player.PotionSlots.Any(p => p is FruitJuice))
            throw new InvalidOperationException("Policy fixture must retain original rejection and new conditional proof: "
                + root.ComponentHealingRejection + "/" + root.PruningComponentHealingRejection);
        var parent = root.ForkSimulator();
        string Full(CombatPredictionSimulator sim) => DescribeContinuationContractState(sim, root, player)
            + "\nHISTORY=" + CardContinuationContractHistoryText(sim);
        string parentBefore = Full(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        int Bound(CombatPredictionSimulator sim, bool include = true, int? quota = null)
            => StrategicHpRecoveryBound.ComponentHealingUpperBound(sim, player, 0,
                includePotionHealing: include, maximumExplicitPotionUses: quota, useReviewedSources: true);
        var active = parent.Fork();
        using (SimulationNotificationIsolation.Enter())
        {
            var combat = (SimulatedCombatState)active.State.CombatState;
            combat.SetAmount<RegenPower>(player.Creature, 3);
            if (Bound(parent) != int.MaxValue || Bound(active) != int.MaxValue
                || Bound(parent, false) != 0 || Bound(parent, quota: 0) != 0
                || Bound(active, false) != 6 || Bound(active, quota: 0) != 6
                || Bound(active.Fork(), false) != 6)
                throw new InvalidOperationException("Legal Fruit must stay unknown and active Regen survive ban/zero quota.");
            foreach (PileType pile in new[] { PileType.Hand, PileType.Exhaust })
            {
                var unknown = active.Fork();
                unknown.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Feed>(), player), pile,
                    player, resultKind: CardGenerationResultKind.Fixed);
                if (Bound(unknown, false) != int.MaxValue)
                    throw new InvalidOperationException("No-use policy accepted unknown growth source in " + pile);
            }
            var unknownPower = active.Fork();
            ((SimulatedCombatState)unknownPower.State.CombatState).SetAmount<ReattachPower>(player.Creature, 9);
            if (Bound(unknownPower, false) != int.MaxValue)
                throw new InvalidOperationException("No-use policy accepted player revival power.");
        }
        var children = Enumerable.Range(1, 16).Select(amount => (amount, sim: active.Fork())).ToArray();
        await Task.WhenAll(children.Select(child => Task.Run(() =>
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            ((SimulatedCombatState)child.sim.State.CombatState).SetAmount<RegenPower>(player.Creature, child.amount);
            if (Bound(child.sim) != int.MaxValue || Bound(child.sim, quota: 0) != child.amount * (child.amount + 1) / 2)
                throw new InvalidOperationException("Owned Regen policy bound differs in child.");
        })));
        foreach (var child in children)
        {
            var grandchild = child.sim.Fork();
            if (Full(child.sim) != Full(grandchild)
                || Bound(grandchild, false) != child.amount * (child.amount + 1) / 2)
                throw new InvalidOperationException("Policy recovery bound or complete state differs after second-generation Fork.");
        }
        var names = SolverDisplayNames.Capture(live);
        var damage = BattleDamageTracker.Observe(live);
        var policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null);
        var zero = new CombatBeamSolver(root, names, damage, policy, maximumPotionUses: 0).TaskPolicyRecoveryFlags();
        var open = new CombatBeamSolver(root, names, damage, policy).TaskPolicyRecoveryFlags();
        if (!zero.component || zero.expanded != open.expanded
            || open.expanded != CombatBeamSolver.CanUseReviewedGrowthHpProof(root, policy))
            throw new InvalidOperationException("Conditional source proof escaped its zero-use member.");
        if (Full(parent) != parentBefore || Bound(active, false) != 6
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Policy recovery modified parent/live or sibling.");
        _completedChecks.Add("PolicyRecovery:OriginalScheduleRejected:ConditionalSourcesAccepted:LegalFruitUnknown:NoUseFruitExcluded:ActiveRegenPreserved:UnknownGrowthBothPiles:PlayerRevivalRejected:SixteenParallelBoundsTwoGenerationFork:ParentLiveIsolation");
        _completedChecks.Add("TASK_POLICY_RECOVERY " + JsonSerializer.Serialize(new {
            originalRejection = root.ComponentHealingRejection, conditionalRejection = root.PruningComponentHealingRejection,
            legalBound = Bound(parent), bannedBound = Bound(parent, false), regenBannedBound = Bound(active, false),
            zeroMember = new { zero.expanded, zero.local, zero.component },
            openMember = new { open.expanded, open.local, open.component }, forkCount = children.Length,
            parentUnchanged = Full(parent) == parentBefore, actualPrunes = 0, fullCoordinator = false }));
    }
}

